<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { actualizarTurnoExtra, cambiarEstadoTurnoExtra, crearTurnoExtra, listarTurnosExtra } from '../services/turnosExtra'
import type { HorarioTrabajo, RegimenHorario } from '../interfaces/horario.interface'
import type { ConceptoTurnoOption, TurnoExtra, TurnoExtraPayload } from '../interfaces/turnoExtra.interface'
const rows=ref<TurnoExtra[]>([]),horarios=ref<HorarioTrabajo[]>([]),regimenes=ref<RegimenHorario[]>([]),conceptos=ref<ConceptoTurnoOption[]>([]),regimenId=ref<number|null>(null),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),modal=ref(false),editing=ref<number|null>(null),error=ref(''),success=ref('')
const blank=():TurnoExtraPayload=>({horario_id:0,concepto_id:null,hora_inicio:'',hora_fin:''}),form=reactive<TurnoExtraPayload>(blank()),time=(v:string)=>v.slice(0,5),message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
const estimate=computed(()=>{if(!form.hora_inicio||!form.hora_fin)return null;const value=(v:string)=>{const p=v.split(':').map(Number);return(p[0]??0)*60+(p[1]??0)},start=value(form.hora_inicio),rawEnd=value(form.hora_fin),cross=rawEnd<=start,end=cross?rawEnd+1440:rawEnd,total=end-start;return{cross,text:`${Math.floor(total/60)}h ${total%60}m`}})
async function load(next=1){loading.value=true;error.value='';try{const r=await listarTurnosExtra(regimenId.value,next);rows.value=r.data;horarios.value=r.horarios;regimenes.value=r.regimenes;conceptos.value=r.conceptos;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(v){error.value=message(v)}finally{loading.value=false}}
function open(item?:TurnoExtra){editing.value=item?.id??null;Object.assign(form,item?{horario_id:item.horario_id,concepto_id:item.concepto_id,hora_inicio:time(item.hora_inicio),hora_fin:time(item.hora_fin)}:blank());modal.value=true;error.value=''}
async function save(){if(!form.horario_id||!form.hora_inicio||!form.hora_fin)return void(error.value='Seleccione el horario y complete las horas de inicio y fin.');saving.value=true;try{editing.value?await actualizarTurnoExtra(editing.value,{...form}):await crearTurnoExtra({...form});success.value=`Turno extra ${editing.value?'actualizado':'registrado'} correctamente.`;modal.value=false;await load(page.value)}catch(v){error.value=message(v)}finally{saving.value=false}}
async function toggle(item:TurnoExtra){if(!confirm(`¿Desea ${item.estado?'desactivar':'activar'} este turno extra?`))return;try{await cambiarEstadoTurnoExtra(item.id);success.value='Estado actualizado correctamente.';await load(page.value)}catch(v){error.value=message(v)}}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink to="/modulos/administracion/recursos">Recursos Humanos</RouterLink> / Turnos extra</nav><header class="hero"><div class="mark">TE</div><div><small>MIA · RR. HH. · CONTROL DE TIEMPOS</small><h1>Turnos extra</h1><p>Configura turnos adicionales y su concepto de planilla asociado.</p></div><button @click="open()">Nuevo turno extra</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error&&!modal" class="flash error">{{error}}</p><form class="filters" @submit.prevent="load(1)"><select v-model="regimenId"><option :value="null">Todos los regímenes</option><option v-for="r in regimenes" :key="r.id" :value="r.id">[{{r.codigo}}] {{r.descripcion}}</option></select><button>Filtrar</button><button v-if="regimenId" type="button" class="soft" @click="regimenId=null;load(1)">Limpiar</button></form><section class="card"><div v-if="loading" class="empty">Consultando turnos…</div><div v-else-if="!rows.length" class="empty">No se encontraron turnos extra registrados.</div><div v-else class="scroll"><table><thead><tr><th>ID</th><th>Horario</th><th>Régimen</th><th>Desde</th><th>Hasta</th><th>Cruza día</th><th>Concepto</th><th>Duración</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td>#{{item.id}}</td><td><b>{{item.horario?.codigo||'—'}}</b><small>{{item.horario?.descripcion}}</small></td><td>{{item.horario?.regimen?`[${item.horario.regimen.codigo}] ${item.horario.regimen.descripcion}`:'—'}}</td><td>{{time(item.hora_inicio)}}</td><td>{{time(item.hora_fin)}}</td><td><span :class="item.cruza_dia?'cross':'normal'">{{item.cruza_dia?'SÍ':'NO'}}</span></td><td><b>{{item.concepto?.codigo||'—'}}</b><small>{{item.concepto?.descripcion||'Sin concepto'}}</small></td><td>{{Math.floor(item.minutos_turno/60)}}h {{item.minutos_turno%60}}m</td><td><span :class="item.estado?'active':'inactive'">{{item.estado?'ACTIVO':'INACTIVO'}}</span></td><td class="actions"><button @click="open(item)">Editar</button><button :class="item.estado?'disable':'enable'" @click="toggle(item)">{{item.estado?'Desactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}} · {{total}} turnos</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="modal" class="overlay" @click.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><small>CONTROL DE TIEMPOS</small><h2>{{editing?'Editar':'Nuevo'}} turno extra</h2></div><button type="button" @click="modal=false">×</button></header><p v-if="error" class="flash error">{{error}}</p><div class="grid"><label>Horario de trabajo *<select v-model="form.horario_id"><option :value="0">Seleccione</option><option v-for="h in horarios" :key="h.id" :value="h.id">[{{h.codigo}}] {{h.descripcion}} - {{h.regimen?.codigo}}</option></select></label><label>Concepto (opcional)<select v-model="form.concepto_id"><option :value="null">Sin concepto</option><option v-for="c in conceptos" :key="c.id" :value="c.id">[{{c.codigo}}] {{c.descripcion}}</option></select></label><label>Hora inicio *<input v-model="form.hora_inicio" type="time"></label><label>Hora fin *<input v-model="form.hora_fin" type="time"><small>Si es menor o igual al inicio, cruza al día siguiente.</small></label><aside v-if="estimate"><b>{{estimate.text}}</b><span>Duración estimada</span><em v-if="estimate.cross">Cruza al día siguiente</em></aside></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar turno'}}</button></footer></form></div></div></template>
<style scoped>
