r{padding:15px;display:flex;align-items:center;justify-content:space-between}.modal h2{margin:2px 0;font-size:1.05rem}.modal>header button{color:#64727a;background:#edf1f3;font-size:1rem}.grid{padding:12px 15px;display:grid;grid-template-columns:1fr 1fr;gap:12px}.grid label{display:grid;gap:5px;font-size:.5rem;font-weight:700}.grid label small{color:#8b969b;font-weight:400}.grid aside{grid-column:1/-1;padding:12px;display:flex;align-items:center;gap:10px;border-radius:7px;background:#e8f5f7;font-size:.5rem}.grid aside b{font-size:.8rem}.grid aside em{margin-left:auto;color:#9a6816;font-style:normal}@media(max-width:650px){.grid{grid-template-columns:1fr}.grid aside{grid-column:auto}.filters{flex-direction:column}.filters select{min-width:0}.hero p{display:none}}
</style>
